SELECT 'датчик файлов дерева «repo-file» ' || fact_gap($1, 'repo-file') || ': есть ли каталоги задач — неизвестно, и это не зелёное' AS detail WHERE NOT (fact_fresh($1, 'repo-file') OR fact_fresh($1, 'code-file')) AND EXISTS (SELECT 1 FROM project_task_tree_leaf l WHERE l.project_id = $1 AND l.is_path AND NOT l.exempt) UNION ALL SELECT l.task_id || ' — ' || l.leaf || ': нет даже каталога ' || l.target_dir  FROM project_task_tree_leaf l WHERE l.project_id = $1 AND (fact_fresh($1, 'repo-file') OR fact_fresh($1, 'code-file')) AND l.is_path AND NOT l.exempt AND NOT l.forward_declared AND l.target_dir <> '' AND l.op <> '+' AND NOT EXISTS (SELECT 1 FROM project_code_dir d WHERE d.project_id = l.project_id AND d.dir = l.target_dir) ORDER BY 1
